@dataclass
class ScreeningFinding:
    finding_id: str
    risk_type: str
    rule_source: str
    target_item_seqs: list
    drugs: list                      # list[DrugRef]
    dur_rule_texts: list             # DUR 기준 문구 — Screening 사실, evidence 아님
