    effect_name: Optional[str] = None
    canonical_pair_id: Optional[str] = None

    def __post_init__(self):
        if self.risk_type not in SUPPORTED_RISK_TYPES:
            raise ValueError(f"지원하지 않는 risk_type: {self.risk_type!r} (허용: {SUPPORTED_RISK_TYPES})")
        if not self.target_item_seqs or not all(isinstance(s, str) and re.fullmatch(r"\d{9}", s) for s in self.target_item_seqs):
            raise ValueError(f"target_item_seqs는 9자리 문자열 ITEM_SEQ 목록이어야 합니다: {self.target_item_seqs!r}")

