# [nb 05_rag_generation.ipynb cell 23] _uniq
def _uniq(values):
    return sorted({str(v).strip() for v in values if v is not None and not pd.isna(v) and str(v).strip()})

# [nb 05_rag_generation.ipynb cell 23] _contra_ingredients
def _contra_ingredients(pid, item):
    ev = cevi_lu[cevi_lu["canonical_pair_id"] == pid]
    return _uniq(pd.concat([ev.loc[ev["item_seq"] == item, "ingredient_name_kor"],
                            ev.loc[ev["mixture_item_seq"] == item, "mixture_ingredient_name_kor"]]))

# [nb 05_rag_generation.ipynb cell 23] finding_from_02_record
def finding_from_02_record(rec, finding_source):
    rt = rec.get("risk_type")
    if rt == "contraindication":
        pid = rec["canonical_pair_id"]
        drugs = [DrugRef(rec[f"drug_{i}_item_seq"], rec.get(f"drug_{i}_item_name"),
                         _contra_ingredients(pid, rec[f"drug_{i}_item_seq"])) for i in (1, 2)]
        return ScreeningFinding(f"contraindication:{pid}", rt, rec["rule_source"], [d.item_seq for d in drugs], drugs,
                                list(rec.get("prohbt_contents") or []), rec, finding_source, canonical_pair_id=pid)
    if rt == "elderly_caution":
        d = DrugRef(rec["item_seq"], rec.get("item_name"), list(rec.get("ingredient_names") or []))
        texts = [rec["prohbt_content"]] if rec.get("prohbt_content") else []
        return ScreeningFinding(f"elderly_caution:{d.item_seq}", rt, rec["rule_source"], [d.item_seq], [d],
                                texts, rec, finding_source)
    if rt == "therapeutic_duplication":
        drugs = [DrugRef(m["item_seq"], m.get("item_name"), list(m.get("ingredient_names") or [])) for m in rec["matched_items"]]
        seqs = list(rec["matched_item_seqs"])
        return ScreeningFinding(f"therapeutic_duplication:{rec['effect_name']}:{'|'.join(seqs)}", rt, rec["rule_source"],
                                seqs, drugs, list(rec.get("prohbt_contents") or []), rec, finding_source,
                                effect_name=rec["effect_name"])
    raise ValueError(f"지원하지 않는 risk_type: {rt!r}")

# [nb 05_rag_generation.ipynb cell 23] findings_from_screening_result
def findings_from_screening_result(result, finding_source="02_screen_patient_output"):
    """02 screen_patient() 결과 → ScreeningFinding 목록"""
    records = result.get("contraindications", []) + result.get("elderly_cautions", []) + result.get("therapeutic_duplications", [])
    return [finding_from_02_record(r, finding_source) for r in records]
